<?php
/** Proof — clients (spec "Proof", 1): Bea adds Acme; duplicates in words; the code uppercased; Priya sees the card without contact details; archive rules; delete needs the admin; contacts. */
require __DIR__ . '/lib.php';
$priya = as_member(26); $marco = as_member(27); $bea = as_member(28); $owner = as_member(1);
$standard = (int) one("INSERT INTO rate_cards (name, currency, created_by) VALUES ('SMOKE Standard', 'USD', 1) RETURNING id");

echo "1. Create\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/clients/save.php', ['name' => 'SMOKE Acme', 'legal_name' => 'Acme Corporation Ltd', 'code' => 'acme', 'email' => 'ap@acme.invalid', 'phone' => '+1 555 0100', 'billing_address' => "1 Main St\nSpringfield", 'tax_id' => 'US-123', 'terms_days' => '45', 'currency' => 'usd', 'po_required' => 'yes', 'rate_card' => $standard, 'notes' => 'SMOKE a note']);
$acme = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $acme > 0 && ($b['location'] ?? '') === '/clients/' . $acme . '?notice=saved' && ($b['did'] ?? '') === 'Added SMOKE Acme', "client_save: 200, record_id $acme, lands on the client (did: " . ($b['did'] ?? '') . ')');
$row = q('SELECT code, currency, terms_days, po_required, default_rate_card_id FROM clients WHERE id = :c', ['c' => $acme])[0];
ok($row['code'] === 'ACME' && $row['currency'] === 'USD' && (int) $row['terms_days'] === 45 && $row['po_required'] && (int) $row['default_rate_card_id'] === $standard, 'the code and currency arrive uppercased (ACME, USD); terms 45, PO required, the Standard card');
$log = activity('client.create', $since);
$after = json_decode((string) ($log[0]['after'] ?? '{}'), true);
ok(count($log) === 1 && (int) $log[0]['client_id'] === $acme && $after['code'] === 'ACME' && $after['has_notes'] === true && !str_contains((string) $log[0]['after'], 'acme.invalid') && !str_contains((string) $log[0]['after'], '555') && !str_contains((string) $log[0]['after'], 'Main St') && !str_contains((string) $log[0]['after'], 'US-123'), 'client.create logged with client_id and the loggable fields — never the email, phone, address or tax id');
[$c, $b] = act($bea, '/clients/save.php', ['name' => 'smoke acme']);
ok($c === 422 && msg($b) === 'A client named SMOKE Acme already exists.', 'a second "Acme" (any case): 422 "A client named SMOKE Acme already exists."');
[$c, $b] = act($bea, '/clients/save.php', ['name' => 'SMOKE Other', 'code' => 'ACME']);
ok($c === 422 && msg($b) === 'The code ACME already belongs to SMOKE Acme.', 'a taken code: 422 naming its owner');
[$c, $b] = act($bea, '/clients/save.php', ['name' => 'SMOKE Bad', 'code' => 'a', 'currency' => 'dollars', 'email' => 'nope', 'terms_days' => '400']);
ok($c === 422 && isset(fields($b)['code'], fields($b)['currency'], fields($b)['email'], fields($b)['terms_days']), 'a bad code, currency, email and terms: 422 with each field named');
[$c, $b] = act($bea, '/clients/save.php', ['name' => 'SMOKE Plain']);
$plain = (int) $b['record_id'];
$row = q('SELECT code, currency, terms_days FROM clients WHERE id = :c', ['c' => $plain])[0];
ok($c === 200 && $row['code'] === null && $row['currency'] === null && $row['terms_days'] === null, 'a client with only a name: no code, currency and terms left to the defaults (null = the settings\')');
[$c, $d] = screen($bea, '/clients/' . $plain);
ok($d['client']['currency'] === null && $d['defaults']['currency'] === 'USD' && $d['defaults']['terms_days'] === 30, 'its page carries the defaults it inherits (USD, 30 days)');

echo "2. Who sees what\n";
[$c, $d] = screen($bea, '/clients/');
$card = array_values(array_filter($d['clients'], fn ($x) => $x['client_id'] === $acme))[0] ?? null;
ok($c === 200 && $card !== null && $card['email'] === 'ap@acme.invalid' && $card['phone'] === '+1 555 0100' && $card['rate_card']['name'] === 'SMOKE Standard' && $card['active_engagements'] === 0, 'Bea (Billing) lists Acme with its email, phone and card');
[$c, $d] = screen($priya, '/clients/');
ok($c === 200 && $d['clients'] === [], 'Priya (Consultant) lists no client yet: she is staffed on no engagement');
$eng = mkengagement($acme, 'SMOKE Acme build', 'active', $standard);
q("INSERT INTO engagement_members (engagement_id, member_id, consulting_role_id, valid_from) VALUES (:e, 26, (SELECT id FROM consulting_roles WHERE key = 'consultant'), '2026-01-01')", ['e' => $eng]);
[$c, $d] = screen($priya, '/clients/');
$card = $d['clients'][0] ?? null;
ok($c === 200 && count($d['clients']) === 1 && $card['client_id'] === $acme && $card['email'] === null && $card['phone'] === null && $card['billing_address'] === null && $card['tax_id'] === null && $card['notes'] === null && $card['active_engagements'] === 1, 'staffed on Acme\'s engagement, Priya sees Acme\'s card — without email, phone, address, tax id or notes');
$body = page($priya, '/clients/' . $acme)['body'];
ok(page($priya, '/clients/' . $acme)['code'] === 200 && !str_contains($body, 'acme.invalid') && !str_contains($body, 'id="client-view-edit-btn"') && !str_contains($body, 'id="client-contact-form"') && str_contains($body, 'id="client-engagement-' . $eng . '"'), 'her page shows the engagement, never the email, no Edit and no contact form');
ok(page($priya, '/clients/' . $acme . '/edit')['code'] === 403 && page($priya, '/clients/' . $plain)['code'] === 404, 'she gets 403 on the form and 404 on a client she may not see');
[$c, $d] = screen($marco, '/clients/');
ok($c === 200 && count($d['clients']) === 1 && $d['clients'][0]['email'] === null, 'Marco (Manager of the engagement) sees Acme — the view admits the managed engagement\'s client — still without the email (clients.manage or billing.write)');
[$c, $d] = screen($bea, '/clients/?q=acm');
ok(count($d['clients']) === 1 && $d['clients'][0]['client_id'] === $acme, 'search by a part of the name finds it');
[$c, $d] = screen($bea, '/clients/?q=ACME');
ok(count($d['clients']) === 1, 'search by the code finds it');

echo "3. Update keeps what it is not sent\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/clients/save.php', ['client' => $acme, 'terms_days' => '30']);
$row = q('SELECT name, code, terms_days, email, po_required FROM clients WHERE id = :c', ['c' => $acme])[0];
ok($c === 200 && (int) $row['terms_days'] === 30 && $row['name'] === 'SMOKE Acme' && $row['code'] === 'ACME' && $row['email'] === 'ap@acme.invalid' && $row['po_required'], 'one field changed; the name, code, email and the PO flag kept (a field left out stays — the browser form always sends the checkbox)');
$log = activity('client.update', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true) === ['terms_days' => 30] && json_decode((string) $log[0]['before'], true) === ['terms_days' => 45], 'client.update logs the changed field only, before and after');
[$c, $b] = act($bea, '/clients/save.php', ['client' => $acme, 'terms_days' => '30']);
ok($c === 200 && count(activity('client.update', $since)) === 1, 'saving the same again logs nothing');
[$c, $b] = act($bea, '/clients/save.php', ['client' => 999999, 'name' => 'x']);
ok($c === 404, 'an unknown client: 404');

echo "4. Contacts\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/clients/contacts/save.php', ['client' => $acme, 'name' => 'SMOKE Jo', 'email' => 'jo@acme.invalid', 'role' => 'Accounts payable', 'receives_invoices' => 'yes', 'is_primary' => 'yes']);
$jo = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $jo > 0 && str_ends_with((string) $b['location'], '/clients/' . $acme . '?notice=contact#client-contacts'), "a contact added: record_id $jo, lands on the client's contacts");
[$c, $b] = act($bea, '/clients/contacts/save.php', ['client' => $acme, 'name' => 'SMOKE Sam', 'role' => 'Sponsor', 'is_primary' => 'yes']);
$sam = (int) $b['record_id'];
ok($c === 200 && q('SELECT is_primary FROM client_contacts WHERE id = :i', ['i' => $jo])[0]['is_primary'] === false && q('SELECT is_primary FROM client_contacts WHERE id = :i', ['i' => $sam])[0]['is_primary'] === true, 'a second primary unsets the first (the index allows one)');
[$c, $b] = act($bea, '/clients/contacts/save.php', ['client' => $acme, 'name' => 'SMOKE Nomail', 'receives_invoices' => 'yes']);
ok($c === 422 && isset(fields($b)['email']), 'a contact who receives invoices needs an email: 422 (field email)');
[$c, $b] = act($bea, '/clients/contacts/save.php', ['contact' => $jo, 'role' => 'AP lead']);
ok($c === 200 && q('SELECT role, email, receives_invoices FROM client_contacts WHERE id = :i', ['i' => $jo])[0] === ['role' => 'AP lead', 'email' => 'jo@acme.invalid', 'receives_invoices' => true], 'changing a contact keeps what it is not sent');
$log = activity('client_contact.save', $since);
ok(count($log) === 3 && !str_contains(json_encode(array_column($log, 'after')), 'acme.invalid') && (int) $log[0]['client_id'] === $acme, 'client_contact.save logged thrice with client_id, never the email');
[$c, $d] = screen($bea, '/clients/' . $acme);
ok(count($d['contacts']) === 2 && $d['contacts'][0]['name'] === 'SMOKE Sam' && $d['contacts'][0]['is_primary'] === true && $d['contacts'][1]['email'] === 'jo@acme.invalid', 'the page lists both, the primary first, with emails for Billing');
[$c, $d] = screen($priya, '/clients/' . $acme);
ok(count($d['contacts']) === 2 && $d['contacts'][1]['email'] === null, 'Priya sees the contacts\' names, not their emails');
[$c, $b] = act($bea, '/clients/contacts/remove.php', ['contact' => $sam]);
ok($c === 200 && one('SELECT archived_at FROM client_contacts WHERE id = :i', ['i' => $sam]) !== null && count(activity('client_contact.remove', $since)) === 1, 'a contact removed (archived, logged)');
[$c, $d] = screen($bea, '/clients/' . $acme);
ok(count($d['contacts']) === 1, 'and gone from the page');

echo "5. Archive, restore, delete\n";
[$c, $b] = act($bea, '/clients/archive.php', ['client' => $acme]);
ok($c === 422 && msg($b) === 'SMOKE Acme has 1 active engagement; close them first.', 'archive with an active engagement: 422 "SMOKE Acme has 1 active engagement; close them first."');
q("UPDATE engagements SET status = 'closed' WHERE id = :e", ['e' => $eng]);
$since = last_activity_id();
[$c, $b] = act($bea, '/clients/archive.php', ['client' => $acme]);
ok($c === 200 && one('SELECT archived_at FROM clients WHERE id = :c', ['c' => $acme]) !== null && count(activity('client.archive', $since)) === 1 && ($b['location'] ?? '') === '/clients/?notice=archived', 'closed: archived, logged, lands on the list');
[$c, $d] = screen($bea, '/clients/');
ok(!in_array($acme, array_column($d['clients'], 'client_id'), true), 'gone from the live list');
[$c, $d] = screen($bea, '/clients/?archived=1');
ok(in_array($acme, array_column($d['clients'], 'client_id'), true) && $d['clients'][0]['archived'] === true, 'listed among the archived');
ok(page($bea, '/clients/' . $acme)['code'] === 200 && page($bea, '/clients/' . $acme . '/edit')['code'] === 422, 'its page still opens; the form refuses an archived client');
[$c, $b] = act($bea, '/clients/save.php', ['name' => 'SMOKE Acme']);
$acme2 = (int) $b['record_id'];
ok($c === 200 && $acme2 > $acme, 'the name is free again for a new client');
[$c, $b] = act($bea, '/clients/restore.php', ['client' => $acme]);
ok($c === 422 && str_contains(msg($b), 'A live client named SMOKE Acme exists now'), 'restoring the old one while the name is taken: 422 in words');
[$c, $b] = act($bea, '/clients/archive.php', ['client' => $acme2]);
[$c, $b] = act($bea, '/clients/restore.php', ['client' => $acme]);
ok($c === 200 && one('SELECT archived_at FROM clients WHERE id = :c', ['c' => $acme]) === null && count(activity('client.restore', 0)) === 1, 'the other archived: restored, logged');
[$c, $b] = act($bea, '/clients/delete.php', ['client' => $acme2]);
ok($c === 403, 'delete needs the admin: 403 for Billing');
[$c, $b] = act($owner, '/clients/delete.php', ['client' => $acme]);
ok($c === 422 && str_contains(msg($b), 'has 1 engagement; a client with history is archived, never deleted'), 'the admin cannot delete a client with an engagement: 422 in words');
$since = last_activity_id();
[$c, $b] = act($owner, '/clients/delete.php', ['client' => $acme2]);
ok($c === 200 && (int) one('SELECT count(*) FROM clients WHERE id = :c', ['c' => $acme2]) === 0 && count(activity('client.delete', $since)) === 1, 'a client with no engagement: deleted, logged');

echo "6. Documents and notes on the client\n";
$tmp = tempnam(sys_get_temp_dir(), 'ctsow') . '.pdf';
file_put_contents($tmp, "%PDF-1.4\n%SMOKE statement of work\n");
$since = last_activity_id();
[$c, $b] = upload($bea, '/engagements/attachments/save.php', ['record_type' => 'client', 'record' => $acme], 'file', $tmp, 'SMOKE SOW.pdf');
$aid = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $aid > 0 && ($b['url'] ?? '') === '/attachments/' . $aid && str_ends_with((string) $b['location'], '/clients/' . $acme . '?notice=attached#documents'), "attachment_add on the client: record_id $aid, the URL, lands on the documents");
$row = q('SELECT record_type, record_id, filename, mime_type, storage_path, client_visible FROM attachments WHERE id = :a', ['a' => $aid])[0];
ok($row['record_type'] === 'client' && (int) $row['record_id'] === $acme && $row['filename'] === 'SMOKE SOW.pdf' && $row['mime_type'] === 'application/pdf' && str_starts_with($row['storage_path'], 'attachments/client/' . $acme . '/') && is_file(dirname(__DIR__, 3) . '/storage/' . $row['storage_path']) && !$row['client_visible'], 'stored under storage/attachments/client/{id}/, a PDF, not client-visible');
$log = activity('attachment.add', $since);
ok(count($log) === 1 && (int) $log[0]['client_id'] === $acme && str_contains((string) $log[0]['after'], 'SMOKE SOW.pdf'), 'attachment.add logged with client_id and the filename');
$r = req('GET', '/attachments/' . $aid, ['jar' => $bea]);
ok($r['code'] === 200 && str_contains($r['headers'], 'application/pdf') && str_contains($r['body'], 'SMOKE statement of work'), 'Bea downloads it through the gate');
ok(req('GET', '/attachments/' . $aid, ['jar' => $priya])['code'] === 200, 'Priya, who sees the client, sees its documents too (the view)');
ok(req('GET', '/attachments/' . $aid)['code'] === 302, 'nobody signed in: sent to the launcher');
[$c, $b] = upload($priya, '/engagements/attachments/save.php', ['record_type' => 'client', 'record' => $acme], 'file', $tmp, 'SMOKE no.pdf');
ok($c === 403 && msg($b) === 'You may not attach files to this client.', 'Priya may not attach to a client (not its writer): 403 in words');
file_put_contents($tmp2 = tempnam(sys_get_temp_dir(), 'ctbad') . '.sh', "#!/bin/sh\necho no\n");
[$c, $b] = upload($bea, '/engagements/attachments/save.php', ['record_type' => 'client', 'record' => $acme], 'file', $tmp2, 'evil.sh');
ok($c === 422 && str_contains(msg($b), 'not accepted'), 'a shell script: 422 "That kind of file is not accepted…"');
[$c, $b] = act($bea, '/engagements/notes/save.php', ['record_type' => 'client', 'record' => $acme, 'body' => 'SMOKE Jo prefers invoices on the 1st']);
$nid = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $nid > 0 && (int) one('SELECT client_id FROM activity_log WHERE action = \'note.add\' ORDER BY id DESC LIMIT 1') === $acme, "note_add on the client: record_id $nid, logged with client_id");
[$c, $d] = screen($bea, '/clients/' . $acme);
ok(count($d['notes']) === 1 && $d['notes'][0]['body'] === 'SMOKE Jo prefers invoices on the 1st' && count($d['attachments']) === 1 && count($d['timeline']) >= 5 && $d['timeline'][0]['sentence'] !== '', 'the client page carries the note, the document and the timeline in words (' . ($d['timeline'][0]['sentence'] ?? '') . ')');
[$c, $d] = screen($priya, '/clients/' . $acme);
ok(count($d['notes']) === 1 && count($d['attachments']) === 1 && $d['timeline'] === [], 'Priya sees the note and the document; the trail shows her only her own rows (none here)');
[$c, $b] = act($priya, '/engagements/notes/delete.php', ['note' => $nid]);
ok($c === 422 && msg($b) === 'Only its author or the admin removes a note.', 'Priya may not remove Bea\'s note: 422 in words');
[$c, $b] = act($bea, '/engagements/notes/delete.php', ['note' => $nid]);
ok($c === 200 && (int) one('SELECT count(*) FROM notes WHERE id = :n', ['n' => $nid]) === 0, 'its author removes it');
[$c, $b] = act($bea, '/engagements/attachments/delete.php', ['attachment' => $aid]);
clearstatcache();                                        // PHP caches is_file(): the earlier check would otherwise answer from memory
ok($c === 200 && (int) one('SELECT count(*) FROM attachments WHERE id = :a', ['a' => $aid]) === 0 && !is_file(dirname(__DIR__, 3) . '/storage/' . $row['storage_path']), 'attachment_delete removes the row and the file' . ($c === 200 ? '' : " ($c " . msg($b) . ')'));
@unlink($tmp); @unlink($tmp2);
finish();
